// ratelimit.go
package ratelimit

import (
	"errors"
	"sync"
	"time"
)

// Clock abstracts time for testability.
type Clock interface {
	Now() time.Time
}

type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// Limiter is a concurrency-safe token-bucket rate limiter.
// Zero value is not usable; use New.
type Limiter struct {
	mu       sync.Mutex
	tokens   float64
	last     time.Time
	rate     float64 // tokens per second
	burst    float64
	clock    Clock
	nowFn    func() time.Time // fast path when clock is realClock
}

// New creates a Limiter with the given refill rate (tokens per second)
// and burst capacity. rate and burst must be > 0.
func New(rate, burst float64) (*Limiter, error) {
	return NewWithClock(rate, burst, nil)
}

// NewWithClock is New with an injectable Clock; nil means real time.
func NewWithClock(rate, burst float64, c Clock) (*Limiter, error) {
	if rate <= 0 {
		return nil, errors.New("ratelimit: rate must be > 0")
	}
	if burst <= 0 {
		return nil, errors.New("ratelimit: burst must be > 0")
	}
	if c == nil {
		c = realClock{}
	}
	l := &Limiter{
		tokens: burst,
		rate:   rate,
		burst:  burst,
		clock:  c,
	}
	if rc, ok := c.(realClock); ok {
		_ = rc
		l.nowFn = time.Now
	}
	return l, nil
}

func (l *Limiter) now() time.Time {
	if l.nowFn != nil {
		return l.nowFn()
	}
	return l.clock.Now()
}

// advance refills tokens up to t and updates last.
// Caller must hold l.mu.
func (l *Limiter) advance(t time.Time) {
	if !l.last.IsZero() {
		if elapsed := t.Sub(l.last); elapsed > 0 {
			l.tokens += elapsed.Seconds() * l.rate
			if l.tokens > l.burst {
				l.tokens = l.burst
			}
		}
	}
	l.last = t
}

// AllowN reports whether n events may happen at time t.
// It consumes n tokens if allowed.
func (l *Limiter) AllowN(t time.Time, n int) bool {
	if n < 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()
	l.advance(t)
	if float64(n) <= l.tokens {
		l.tokens -= float64(n)
		return true
	}
	return false
}

// Allow reports whether one event may happen now.
func (l *Limiter) Allow() bool {
	return l.AllowN(l.now(), 1)
}

// AllowAt reports whether one event may happen at time t.
func (l *Limiter) AllowAt(t time.Time) bool {
	return l.AllowN(t, 1)
}

// Tokens returns the current number of available tokens at time t.
func (l *Limiter) Tokens(t time.Time) float64 {
	l.mu.Lock()
	defer l.mu.Unlock()
	l.advance(t)
	return l.tokens
}
