func TestConcurrentAllow(t *testing.T) {
	fc := &fakeClock{t: time.Unix(0, 0)}
	l, _ := NewWithClock(1000, 100, fc)
	var mu sync.Mutex
	allowed := 0
	var wg sync.WaitGroup
	for i := 0; i < 200; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			if l.AllowN(fc.t, 1) {
				mu.Lock()
				allowed++
				mu.Unlock()
			}
		}()
	}
	wg.Wait()
	if allowed != 100 {
		t.Fatalf("allowed = %d, want 100", allowed)
	}
}
